SELECT
FROM t_category c LEFT JOIN t_test t ON t.category_id = c.id AND t.deleted = 0 WHERE c.deleted = 0
AND c.category_name LIKE CONCAT('%', #{query.keyword}, '%')
AND c.status = #{query.status}
GROUP BY c.id, c.category_name, c.status, c.sort_no, c.update_date ORDER BY c.sort_no DESC, c.id DESC LIMIT #{offset}, #{size}
